// Gallery: poems from the repo, each labelled with where it came from. Seeded samples were generated by the repo's
// Python at build time and can be recreated in Compose with the same seed.
import { route, api, app, esc } from './core.js';
import { FORM_NAMES, sendToAnalyse } from './ui.js';

const card = (p, i, extra = '') => `<div class="card">
  <b>${esc(p.title)}</b>
  <pre>${esc(p.text)}</pre>
  <div class="src">${extra}</div>
  <button type="button" class="alt" data-an="${i}">Analyse</button></div>`;

route('gallery', async () => {
  const s = await api('/samples');
  const all = [];
  const add = p => { all.push(p); return all.length - 1; };
  const seeded = s.seeded.map(p => ({ ...p, title: `${FORM_NAMES[p.form]} · ${p.mood || 'default mood'} · seed ${p.seed}` }));
  app().innerHTML = `
  <h1 class="glow">Gallery</h1>
  <p class="lead">Poems taken from the repository itself. Nothing here was written for the site.</p>
  <h2>Seeded samples from the generator</h2>
  <p class="mute">Generated by <code>core/generator.py</code> when the site was built. The same seed in Compose gives the
    same poem.</p>
  <div class="grid wide gal">${seeded.map(p => card(p, add(p), `<code>${esc(p.call)}</code> ·
    <a href="#/compose?form=${p.form}&mood=${p.mood || ''}&seed=${p.seed}">open in Compose</a>`)).join('')}</div>
  <h2>Example output in the README</h2>
  <p class="mute">Recorded in <code>core/README.md</code> from an earlier run of <code>main.py</code> (before the fixes
    listed on the About page, and without a seed, so it cannot be recreated exactly).</p>
  <div class="grid wide gal">${s.readme.map(p => card(p, add(p), esc(p.source))).join('')}</div>
  <h2>Poems the code analyses</h2>
  <p class="mute">Quoted in the demo scripts: the <code>main.py</code> example and the simple version's sample poems
    (Shakespeare's Sonnet 18 and Emily Dickinson, both public domain).</p>
  <div class="grid wide gal">${s.quoted.map(p => card(p, add(p), esc(p.source))).join('')}</div>`;
  app().querySelectorAll('[data-an]').forEach(b => b.addEventListener('click', () => sendToAnalyse(all[+b.dataset.an].text)));
});
